# ------------------------------------------------------------------------------------------------ Nightingale's diagram
def wedges(cx, cy, radii, cls="ln thin"):
    out = []
    for k, r in enumerate(radii):
        a1, a2 = math.radians(30 * k - 90), math.radians(30 * (k + 1) - 90)
        x1, y1 = cx + r * math.cos(a1), cy + r * math.sin(a1)
        x2, y2 = cx + r * math.cos(a2), cy + r * math.sin(a2)
        out.append(PATH(f"M{cx} {cy} L {x1:.1f} {y1:.1f} A {r} {r} 0 0 1 {x2:.1f} {y2:.1f} Z", cls))
    return out


ng = wedges(200, 290, [60, 80, 110, 150, 175, 160, 130, 100, 80, 70, 60, 55], "ln") + [C(200, 290, 6, "pivot")]
ng += wedges(560, 330, [40, 38, 34, 30, 26, 22, 20, 18, 16, 15, 14, 14]) + [C(560, 330, 4, "pivot")]
ng += [L(20, 290, 380, 290, "sight"), L(200, 110, 200, 470, "sight"), R(430, 470, 260, 110, "ln thin"), L(560, 470, 560, 580, "ln thin")]

